const $ = (selector) => document.querySelector(selector);
const $$ = (selector) => Array.from(document.querySelectorAll(selector));
const money = (value) => Number(value || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const dateBR = (value) => value ? new Date(String(value).replace(' ', 'T') + (String(value).includes('Z') ? '' : 'Z')).toLocaleDateString('pt-BR') : '—';
const escapeHtml = (value) => String(value ?? '').replace(/[&<>'"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#039;', '"': '&quot;' }[char]));
const state = { products: [], orders: [], currentSection: 'dashboard', whatsappTimer: null, staff: [] };

async function api(url, options = {}) {
  const response = await fetch(url, { credentials: 'same-origin', ...options });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    if (response.status === 401 && !url.includes('/auth/login')) showLogin();
    throw new Error(data.error || 'Não foi possível concluir a operação.');
  }
  return data;
}

function showLogin() { $('#login-view').classList.remove('hidden'); $('#app-view').classList.add('hidden'); }
function showApp() { $('#login-view').classList.add('hidden'); $('#app-view').classList.remove('hidden'); }
function toast(message) { const el = $('#toast'); el.textContent = message; el.classList.add('show'); setTimeout(() => el.classList.remove('show'), 2600); }
function openModal(id) { $(`#${id}`).classList.add('open'); }
function closeModal(id) { $(`#${id}`).classList.remove('open'); }

function setSection(section) {
  state.currentSection = section;
  $$('.nav-item').forEach(item => item.classList.toggle('active', item.dataset.section === section));
  $$('.admin-section').forEach(item => item.classList.toggle('active-section', item.id === `section-${section}`));
  const titles = { dashboard: ['CENTRAL DE CONTROLE', 'Visão geral'], products: ['CATÁLOGO', 'Produtos'], orders: ['VENDAS', 'Pedidos'], operations: ['EQUIPE', 'Operação'], team: ['ACESSOS', 'Equipe e permissões'], sellers: ['VENDAS', 'Resultado dos vendedores'], support: ['ATENDIMENTO', 'Atendimentos'], audit: ['RASTREABILIDADE', 'Auditoria'], links: ['ACESSO CONTROLADO', 'Links do catálogo'], stock: ['OPERAÇÃO', 'Estoque'], finance: ['CONTROLE', 'Financeiro'], payables: ['COMPROMISSOS', 'Contas a pagar'], campaigns: ['CALENDÁRIO', 'Campanhas'], purchases: ['SUPRIMENTOS', 'Compras e fornecedores'], customers: ['CADASTROS', 'Novos clientes'], whatsapp: ['ATENDIMENTO', 'WhatsApp Web'] };
  $('#section-eyebrow').textContent = titles[section][0];
  $('#section-title').textContent = titles[section][1];
  if (section === 'dashboard') loadDashboard();
  if (section === 'products') loadProducts();
  if (section === 'orders') loadOrders();
  if (section === 'operations') loadOperations();
  if (section === 'team') loadStaff();
  if (section === 'sellers') loadSellerResults();
  if (section === 'support') loadSupport();
  if (section === 'audit') loadAudit();
  if (section === 'links') loadCatalogLinks();
  if (section === 'stock') loadStock();
  if (section === 'finance') loadExpenses();
  if (section === 'payables') loadPayables();
  if (section === 'campaigns') loadCampaigns();
  if (section === 'purchases') loadPurchases();
  if (section === 'customers') loadCustomerRegistrations();
  if (section === 'whatsapp') { loadWhatsapp(); startWhatsappPolling(); } else stopWhatsappPolling();
}

function statusPill(status) {
  const labels = { pending: 'Pendente', confirmed: 'Confirmado', preparing: 'Em preparo', shipped: 'Enviado', delivered: 'Entregue', cancelled: 'Cancelado', paid: 'Pago', failed: 'Falhou', refunded: 'Estornado' };
  return `<span class="status-pill ${escapeHtml(status)}">${labels[status] || escapeHtml(status)}</span>`;
}

async function loadDashboard() {
  try {
    const data = await api('/api/admin/dashboard');
    $('#metric-revenue').textContent = money(data.revenue); $('#metric-profit').textContent = money(data.profit); $('#metric-orders').textContent = data.orderCount; $('#metric-attention').textContent = Number(data.pendingOrders) + Number(data.lowStock) + Number(data.supportOpen || 0);
    $('#profit-big').textContent = money(data.profit); $('#break-revenue').textContent = money(data.revenue); $('#break-cost').textContent = money(data.cost); $('#break-expenses').textContent = money(data.expenses);
    $('#dashboard-orders').innerHTML = renderOrdersTable(data.openOrders, true);
    bindOrderStatusEvents($('#dashboard-orders'));
  } catch (error) { toast(error.message); }
}

function renderOrdersTable(orders, compact = false) {
  if (!orders.length) return '<div class="empty-state"><strong>Nenhum pedido encontrado.</strong><span>Os novos pedidos aparecerão aqui.</span></div>';
  return `<table class="data-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Total</th><th>Status</th>${compact ? '' : '<th>Pagamento</th>'}<th>Data</th>${compact ? '' : '<th></th>'}</tr></thead><tbody>${orders.map(order => `<tr><td><strong>${escapeHtml(order.order_number)}</strong></td><td>${escapeHtml(order.customer_name)}<small class="table-sub">${escapeHtml(order.customer_phone)}</small></td><td><strong>${money(order.total)}</strong></td><td><select class="status-select" data-order-status="${order.id}"><option value="pending" ${order.status === 'pending' ? 'selected' : ''}>Pendente</option><option value="confirmed" ${order.status === 'confirmed' ? 'selected' : ''}>Confirmado</option><option value="preparing" ${order.status === 'preparing' ? 'selected' : ''}>Em preparo</option><option value="shipped" ${order.status === 'shipped' ? 'selected' : ''}>Enviado</option><option value="delivered" ${order.status === 'delivered' ? 'selected' : ''}>Entregue</option><option value="cancelled" ${order.status === 'cancelled' ? 'selected' : ''}>Cancelado</option></select></td>${compact ? '' : `<td>${statusPill(order.payment_status)}</td>`}<td>${dateBR(order.created_at)}</td>${compact ? '' : `<td><button class="table-action" data-order-detail="${order.id}" type="button">Detalhes</button></td>`}</tr>`).join('')}</tbody></table>`;
}

function bindOrderStatusEvents(scope = document) {
  scope.querySelectorAll('[data-order-status]').forEach(select => select.addEventListener('change', async () => {
    try { await api(`/api/admin/orders/${select.dataset.orderStatus}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: select.value }) }); toast('Status do pedido atualizado.'); loadDashboard(); if (state.currentSection === 'orders') loadOrders(); if (state.currentSection === 'stock') loadStock(); } catch (error) { toast(error.message); }
  }));
  scope.querySelectorAll('[data-order-detail]').forEach(button => button.addEventListener('click', () => showOrderDetail(Number(button.dataset.orderDetail))));
}

async function showOrderDetail(id) {
  try {
    const { order } = await api(`/api/admin/orders/${id}`);
    const items = order.items.map(item => `${item.quantity} × ${escapeHtml(item.name)} — ${money(item.lineTotal)}`).join('\n');
    alert(`${order.order_number}\n\nCliente: ${order.customer_name}\nTelefone: ${order.customer_phone}\nEndereço: ${order.shipping_address}, ${order.shipping_city}/${order.shipping_state}\n\nItens:\n${items}\n\nTotal: ${money(order.total)}\nPagamento: ${order.payment_status}`);
  } catch (error) { toast(error.message); }
}

async function loadProducts() {
  try { state.products = (await api('/api/admin/products')).products; renderProducts(); } catch (error) { toast(error.message); }
}

function renderProducts() {
  const grid = $('#products-grid');
  if (!state.products.length) { grid.innerHTML = '<div class="empty-state card-empty"><strong>Nenhum produto cadastrado.</strong><span>Comece adicionando o primeiro doce.</span></div>'; return; }
  grid.innerHTML = state.products.map(product => `<article class="admin-product-card"><div class="product-image">${product.imageUrl ? `<img src="${product.imageUrl}" alt="${escapeHtml(product.name)}">` : '<div class="image-placeholder"><span>doce</span></div>'}<span class="image-note">${product.active ? 'publicado' : 'oculto'}</span></div><div class="product-info"><h3>${escapeHtml(product.name)}</h3><div class="admin-product-meta"><strong>Cliente: ${money(product.startingPrice ?? product.price)}</strong><small>Repasse: ${money(product.vendorPrice ?? 0)} · Custo: ${money(product.cost ?? 0)}</small>${product.availability === 'made_to_order' ? '<span class="availability made">encomenda</span>' : `<span class="availability ${product.stockQty <= product.lowStockThreshold ? 'low' : 'ready'}">${product.stockQty} em estoque</span>`}</div>${product.priceTiers?.length ? `<small class="price-note">${escapeHtml(formatPriceTiers(product))}</small>` : ''}<div class="admin-card-actions"><button class="outline-button" data-edit-product="${product.id}" type="button">Editar</button><button class="outline-button" data-toggle-product="${product.id}" type="button">${product.active ? 'Ocultar' : 'Publicar'}</button><button class="outline-button danger" data-delete-product="${product.id}" type="button">Excluir</button></div></div></article>`).join('');
  grid.querySelectorAll('[data-edit-product]').forEach(button => button.addEventListener('click', () => openProductForm(Number(button.dataset.editProduct))));
  grid.querySelectorAll('[data-toggle-product]').forEach(button => button.addEventListener('click', async () => {
    const product = state.products.find(item => item.id === Number(button.dataset.toggleProduct));
    try { await api(`/api/admin/products/${product.id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ active: !product.active }) }); toast(product.active ? 'Produto ocultado.' : 'Produto publicado.'); loadProducts(); } catch (error) { toast(error.message); }
  }));
  grid.querySelectorAll('[data-delete-product]').forEach(button => button.addEventListener('click', async () => { if (!confirm('Excluir este produto? O sistema vai desativá-lo para preservar o histórico.')) return; const product = state.products.find(item => item.id === Number(button.dataset.deleteProduct)); try { await api(`/api/admin/products/${product.id}`, { method: 'DELETE' }); toast('Produto excluído/desativado.'); loadProducts(); } catch (error) { toast(error.message); } }));
}

function parsePriceTiers(text, fallbackCost) {
  return String(text || '').split(/\r?\n/).map(line => line.trim()).filter(Boolean).map(line => {
    const parts = line.split('|').map(part => part.trim());
    const range = parts[0] || '';
    const open = range.endsWith('+');
    const bounds = range.replace('+', '').split('-').map(value => Number(String(value).replace(',', '.')));
    if (!Number.isFinite(bounds[0]) || bounds[0] <= 0) throw new Error(`Faixa inválida: ${line}`);
    return { minQty: bounds[0], maxQty: open ? null : (Number.isFinite(bounds[1]) ? bounds[1] : bounds[0]), price: parts[1] || '', cost: parts[2] || fallbackCost || '' };
  });
}

function formatPriceTiers(product) {
  return (product.priceTiers || []).map(tier => `${tier.minQty}${tier.maxQty === null ? '+' : `–${tier.maxQty}`}: ${money(tier.price)}`).join(' · ');
}

function addPriceTierRow(tier = {}) {
  const row = document.createElement('div');
  row.className = 'price-tier-row';
  row.innerHTML = `<input data-tier-min type="number" min="1" step="1" placeholder="Qtd. mínima" value="${escapeHtml(tier.minQty ?? '')}"><input data-tier-price inputmode="decimal" placeholder="Preço unitário" value="${escapeHtml(tier.price ?? '')}"><button class="icon-button tier-remove" data-remove-tier type="button" aria-label="Remover faixa">×</button>`;
  $('#price-tier-rows').appendChild(row);
  row.querySelector('[data-remove-tier]').addEventListener('click', () => { if ($('#price-tier-rows').children.length > 1) row.remove(); });
}

function renderPriceTierRows(tiers = []) {
  const rows = $('#price-tier-rows');
  rows.innerHTML = '';
  (tiers.length ? tiers : [{ minQty: 1, price: '' }]).forEach(addPriceTierRow);
}

function collectPriceTiers(form) {
  const tiers = [];
  $('#price-tier-rows').querySelectorAll('.price-tier-row').forEach((row, index) => {
    const minText = row.querySelector('[data-tier-min]').value.trim();
    const priceText = row.querySelector('[data-tier-price]').value.trim();
    if (!minText && !priceText) return;
    const minQty = Number(minText);
    const price = Number(priceText.replace(',', '.'));
    if (!Number.isInteger(minQty) || minQty < 1 || !Number.isFinite(price) || price < 0) throw new Error(`Revise a faixa ${index + 1}. Informe quantidade inteira e preço válido.`);
    tiers.push({ minQty, maxQty: null, price: priceText, cost: form.elements.cost.value });
  });
  tiers.sort((a, b) => a.minQty - b.minQty);
  if (tiers.some((tier, index) => index > 0 && tier.minQty === tiers[index - 1].minQty)) throw new Error('Não repita a mesma quantidade mínima.');
  return tiers;
}

function setProductPreview(url) { $('#product-image-preview').innerHTML = url ? `<img src="${url}" alt="Prévia">` : '<span>sem imagem</span>'; }
function openProductForm(id = null) {
  const form = $('#product-form'); form.reset(); form.elements.id.value = id || ''; $('#product-modal-title').textContent = id ? 'Editar produto' : 'Novo produto'; setProductPreview(null); renderPriceTierRows(); $('#product-error').textContent = '';
  if (id) { const product = state.products.find(item => item.id === id); if (!product) return; form.elements.name.value = product.name; form.elements.price.value = product.price.toFixed(2).replace('.', ','); form.elements.vendorPrice.value = (product.vendorPrice ?? 0).toFixed(2).replace('.', ','); form.elements.cost.value = product.cost.toFixed(2).replace('.', ','); renderPriceTierRows((product.priceTiers && product.priceTiers.length) ? product.priceTiers : [{ minQty: 1, price: product.price }]); form.elements.stockQty.value = product.stockQty; form.elements.lowStockThreshold.value = product.lowStockThreshold; form.elements.availability.value = product.availability; form.elements.leadTimeDays.value = product.leadTimeDays; form.elements.description.value = product.description; setProductPreview(product.imageUrl); }
  openModal('product-modal');
}

async function saveProduct(event) {
  event.preventDefault();
  const form = event.target; const id = form.elements.id.value; let priceTiers; try { priceTiers = collectPriceTiers(form); } catch (error) { $('#product-error').textContent = error.message; return; } const payload = { name: form.elements.name.value, price: form.elements.price.value, vendorPrice: form.elements.vendorPrice.value, cost: form.elements.cost.value, priceTiers, stockQty: form.elements.stockQty.value, lowStockThreshold: form.elements.lowStockThreshold.value, availability: form.elements.availability.value, leadTimeDays: form.elements.leadTimeDays.value, description: form.elements.description.value };
  const button = form.querySelector('button[type="submit"]'); button.disabled = true; $('#product-error').textContent = '';
  try {
    const data = await api(id ? `/api/admin/products/${id}` : '/api/admin/products', { method: id ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
    const image = $('#product-image').files[0];
    if (image) { const formData = new FormData(); formData.append('image', image); await api(`/api/admin/products/${data.product.id}/image`, { method: 'POST', body: formData }); }
    closeModal('product-modal'); toast(id ? 'Produto atualizado.' : 'Produto cadastrado.'); await loadProducts();
  } catch (error) { $('#product-error').textContent = error.message; } finally { button.disabled = false; }
}

async function loadSellerResults() { try { const { sellers } = await api('/api/admin/seller-results'); $('#seller-results-table').innerHTML = sellers.length ? `<table class="data-table"><thead><tr><th>Vendedor</th><th>Pedidos</th><th>Vendas</th><th>Repasse</th><th>Resultado vendedor</th><th>Margem empresa</th></tr></thead><tbody>${sellers.map(s => `<tr><td><strong>${escapeHtml(s.name)}</strong><small class="table-sub">${escapeHtml(s.phone)}</small></td><td>${s.orders}</td><td>${money(s.sales)}</td><td>${money(s.vendorValue)}</td><td>${money(s.sellerMargin)}</td><td>${money(s.companyGross)}</td></tr>`).join('')}</tbody></table>` : '<div class="empty-state"><strong>Nenhuma venda atribuída.</strong><span>Quando um cliente comprar por um link de vendedor, o resultado aparecerá aqui.</span></div>'; } catch (error) { toast(error.message); } }
async function loadSupport() { try { const { tickets } = await api('/api/admin/support'); $('#support-table').innerHTML = tickets.length ? `<table class="data-table"><thead><tr><th>Protocolo</th><th>Cliente</th><th>Status</th><th>Responsável</th><th>Data</th></tr></thead><tbody>${tickets.map(t => `<tr><td><strong>ATD-${String(t.id).padStart(5,'0')}</strong></td><td>${escapeHtml(t.customer_name)}<small class="table-sub">${escapeHtml(t.customer_phone)}</small></td><td>${escapeHtml(t.status)}</td><td>${escapeHtml(t.staff_name || 'Aguardando')}</td><td>${dateBR(t.created_at)}</td></tr>`).join('')}</tbody></table>` : '<div class="empty-state"><strong>Nenhum atendimento.</strong><span>Os chamados do WhatsApp aparecerão aqui.</span></div>'; } catch (error) { toast(error.message); } }
async function loadAudit() { try { const { logs } = await api('/api/admin/audit'); $('#audit-table').innerHTML = logs.length ? `<table class="data-table"><thead><tr><th>Data</th><th>Quem</th><th>Ação</th><th>Entidade</th><th>Detalhes</th></tr></thead><tbody>${logs.map(l => `<tr><td>${dateBR(l.created_at)}</td><td>${escapeHtml(l.actor_name || l.actor_type)}</td><td>${escapeHtml(l.action)}</td><td>${escapeHtml(l.entity_type)} ${l.entity_id || ''}</td><td>${escapeHtml(JSON.stringify(l.details || {}))}</td></tr>`).join('')}</tbody></table>` : '<div class="empty-state"><strong>Nenhuma ação registrada.</strong></div>'; } catch (error) { toast(error.message); } }

async function loadCatalogLinks() {
  try {
    const { links } = await api('/api/admin/catalog-links');
    $('#catalog-links-table').innerHTML = links.length ? `<table class="data-table"><thead><tr><th>Criado</th><th>Expira</th><th>Vendedor</th><th>Status</th><th>Ações</th></tr></thead><tbody>${links.map(item => `<tr><td>${dateBR(item.createdAt)}</td><td>${dateBR(item.expiresAt)} ${new Date(item.expiresAt).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}</td><td>${escapeHtml(item.salespersonName || '—')}</td><td>${statusPill(item.status === 'available' ? 'paid' : item.status === 'used' ? 'confirmed' : 'cancelled')}</td><td>${item.status !== 'expired' ? `<button class="table-action danger" data-revoke-link="${item.id}" type="button">Revogar</button>` : '—'}</td></tr>`).join('')}</tbody></table>` : '<div class="empty-state"><strong>Nenhum link criado.</strong><span>Gere um link quando quiser enviar o catálogo a um cliente.</span></div>';
    $('#catalog-links-table').querySelectorAll('[data-revoke-link]').forEach(button => button.addEventListener('click', async () => { if (!confirm('Revogar este link?')) return; try { await api(`/api/admin/catalog-links/${button.dataset.revokeLink}`, { method: 'DELETE' }); toast('Link revogado.'); loadCatalogLinks(); } catch (error) { toast(error.message); } }));
  } catch (error) { toast(error.message); }
}

async function createCatalogLink() {
  const button = $('#new-catalog-link'); button.disabled = true;
  try {
    const data = await api('/api/admin/catalog-links', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
    try { await navigator.clipboard.writeText(data.url); toast('Link criado e copiado.'); } catch { window.prompt('Copie este link:', data.url); }
    loadCatalogLinks();
  } catch (error) { toast(error.message); } finally { button.disabled = false; }
}

async function loadOrders() { try { state.orders = (await api('/api/admin/orders')).orders; $('#orders-table').innerHTML = renderOrdersTable(state.orders); bindOrderStatusEvents($('#orders-table')); } catch (error) { toast(error.message); } }

async function loadOperations() { try { const [{ orders }, { staff }] = await Promise.all([api('/api/admin/operations/orders'), api('/api/admin/staff')]); state.staff = staff; const vendors = staff.filter(s => s.active && s.canSell); const pickers = staff.filter(s => s.active && s.canPick); const drivers = staff.filter(s => s.active && s.canDeliver); const opts=(list,selected,empty='—')=>`<option value="">${empty}</option>${list.map(s=>`<option value="${s.id}" ${Number(selected)===Number(s.id)?'selected':''}>${escapeHtml(s.name)}</option>`).join('')}`; $('#operations-table').innerHTML = orders.length ? `<table class="data-table"><thead><tr><th>Pedido</th><th>Cliente/endereço</th><th>Separação</th><th>Vendedor</th><th>Separador</th><th>Entregador</th><th>Entrega</th><th></th></tr></thead><tbody>${orders.map(item => `<tr><td><strong>${escapeHtml(item.order_number)}</strong><small class="table-sub">${money(item.total)}</small></td><td>${escapeHtml(item.customer_name)}<small class="table-sub">${escapeHtml(item.shipping_address)}, ${escapeHtml(item.shipping_city)}/${escapeHtml(item.shipping_state)}</small></td><td><select class="status-select" data-op-picking="${item.id}"><option value="waiting" ${item.picking_status==='waiting'?'selected':''}>Aguardando</option><option value="separating" ${item.picking_status==='separating'?'selected':''}>Separando</option><option value="separated" ${item.picking_status==='separated'?'selected':''}>Separado</option><option value="blocked" ${item.picking_status==='blocked'?'selected':''}>Pendência</option></select></td><td><select class="status-select" data-op-vendor="${item.id}">${opts(vendors,item.salesperson_id)}</select></td><td><select class="status-select" data-op-picker="${item.id}">${opts(pickers,item.picker_id)}</select></td><td><select class="status-select" data-op-driver="${item.id}">${opts(drivers,item.driver_id)}</select></td><td><select class="status-select" data-op-delivery="${item.id}"><option value="not_assigned" ${item.delivery_status==='not_assigned'?'selected':''}>Sem rota</option><option value="queued" ${item.delivery_status==='queued'?'selected':''}>Na fila</option><option value="route" ${item.delivery_status==='route'?'selected':''}>A caminho</option><option value="delivered" ${item.delivery_status==='delivered'?'selected':''}>Entregue</option><option value="failed" ${item.delivery_status==='failed'?'selected':''}>Pendência</option></select></td><td><button class="table-action" data-save-op="${item.id}" type="button">Salvar</button></td></tr>`).join('')}</tbody></table>` : '<div class="empty-state"><strong>Nenhum pedido na fila.</strong><span>Os pedidos confirmados aparecerão aqui para separação.</span></div>'; $('#operations-table').querySelectorAll('[data-save-op]').forEach(b=>b.addEventListener('click',()=>saveOperation(Number(b.dataset.saveOp)))); } catch (error) { toast(error.message); } }

async function saveOperation(id) { const picking=document.querySelector(`[data-op-picking="${id}"]`); const vendor=document.querySelector(`[data-op-vendor="${id}"]`); const picker=document.querySelector(`[data-op-picker="${id}"]`); const driver=document.querySelector(`[data-op-driver="${id}"]`); const delivery=document.querySelector(`[data-op-delivery="${id}"]`); try { await api(`/api/admin/orders/${id}/operations`, {method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({pickingStatus:picking?.value,salespersonId:vendor?.value||null,pickerId:picker?.value||null,driverId:driver?.value||null,deliveryStatus:delivery?.value})}); toast('Operação atualizada.'); loadOperations(); } catch(error){ toast(error.message); } }

async function loadStock() {
  try { const [products, movements] = await Promise.all([api('/api/admin/products'), api('/api/admin/stock/movements')]); state.products = products.products; $('#movement-product').innerHTML = state.products.filter(product => product.active).map(product => `<option value="${product.id}">${escapeHtml(product.name)} — ${product.stockQty} atual</option>`).join(''); $('#stock-table').innerHTML = movements.movements.length ? `<table class="data-table"><thead><tr><th>Data</th><th>Produto</th><th>Tipo</th><th>Quantidade</th><th>Observação</th></tr></thead><tbody>${movements.movements.map(item => `<tr><td>${dateBR(item.created_at)}</td><td><strong>${escapeHtml(item.product_name)}</strong></td><td>${item.type === 'in' ? 'Entrada' : item.type === 'out' ? 'Saída' : 'Ajuste'}</td><td>${item.type === 'out' ? '-' : '+'}${item.quantity}</td><td>${escapeHtml(item.note || '—')}</td></tr>`).join('')}</tbody></table>` : '<div class="empty-state"><strong>Nenhuma movimentação ainda.</strong><span>Registre a primeira entrada do estoque.</span></div>'; } catch (error) { toast(error.message); }
}

