async function loadStaff(){try{const {staff}=await api('/api/admin/staff');state.staff=staff;$('#staff-table').innerHTML=staff.length?`<table class="data-table"><thead><tr><th>Nome</th><th>WhatsApp</th><th>Permissões</th><th>Status</th><th></th></tr></thead><tbody>${staff.map(i=>{const p=[i.canSell&&'Vender',i.canPick&&'Separar',i.canDeliver&&'Entregar',i.canViewFinancial&&'Financeiro',i.canManageProducts&&'Produtos',i.canAttend&&'Atendimento'].filter(Boolean);return `<tr><td><strong>${escapeHtml(i.name)}</strong></td><td>${escapeHtml(i.phone)}</td><td>${p.join(' · ')||'Nenhuma'}</td><td>${i.active?'Ativo':'Inativo'}</td><td><button class="table-action" data-edit-staff="${i.id}" type="button">Editar</button><button class="table-action" data-toggle-staff="${i.id}" type="button">${i.active?'Desativar':'Ativar'}</button></td></tr>`}).join('')}</tbody></table>`:'<div class="empty-state"><strong>Nenhum membro cadastrado.</strong></div>';$('#staff-table').querySelectorAll('[data-edit-staff]').forEach(b=>b.onclick=()=>resetStaffForm(staff.find(x=>x.id===Number(b.dataset.editStaff))));$('#staff-table').querySelectorAll('[data-toggle-staff]').forEach(b=>b.onclick=async()=>{const x=staff.find(x=>x.id===Number(b.dataset.toggleStaff));try{await api(`/api/admin/staff/${x.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({active:!x.active})});toast('Status atualizado.');loadStaff()}catch(e){toast(e.message)}})}catch(e){toast(e.message)}}
