$('#campaign-orders-table').querySelectorAll('[data-campaign-delivery]').forEach(b=>b.onclick=async()=>{const o=orders.find(x=>x.id===Number(b.dataset.campaignDelivery));const status=prompt('Entrega: waiting, in_delivery ou delivered',o.deliveryStatus||'waiting');if(!status)return;try{await api(`/api/admin/campaign-orders/${o.id}/delivery`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({deliveryStatus:status})});toast('Entrega atualizada.');loadCampaignOrders()}catch(e){toast(e.message)}});
