async function boot() {
  try { await api('/api/auth/me'); showApp(); setSection('dashboard'); } catch { showLogin(); }
  $('#login-form').addEventListener('submit', async event => { event.preventDefault(); const form = event.target; $('#login-error').textContent = ''; try { await api('/api/auth/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email: form.elements.email.value, password: form.elements.password.value }) }); showApp(); setSection('dashboard'); } catch (error) { $('#login-error').textContent = error.message; } });
  $$('.nav-item').forEach(button => button.addEventListener('click', () => setSection(button.dataset.section)));
  $$('[data-go]').forEach(button => button.addEventListener('click', () => setSection(button.dataset.go)));
  $$('[data-refresh]').forEach(button => button.addEventListener('click', () => setSection(state.currentSection)));
  $('#logout-button').addEventListener('click', async () => { await api('/api/auth/logout', { method: 'POST' }); showLogin(); });
  $('#mobile-menu').addEventListener('click', () => $('.sidebar').classList.toggle('open'));
  $$('.nav-item').forEach(button => button.addEventListener('click', () => $('.sidebar').classList.remove('open')));
  $$('[data-close-modal]').forEach(button => button.addEventListener('click', () => closeModal(button.dataset.closeModal)));
  document.querySelectorAll('input[name=phone], input[name=postalCode], input[name=amount], input[name=cost], input[name=price], input[name=vendorPrice]').forEach(input => { input.addEventListener('paste', () => setTimeout(() => { if (input.name === 'phone' || input.name === 'postalCode') input.value = input.value.replace(/\D/g,''); }, 0)); });
  $('#refresh-operations').addEventListener('click', loadOperations); $('#new-staff').addEventListener('click', () => resetStaffForm()); $('#new-catalog-link').addEventListener('click', createCatalogLink); $('#staff-form').addEventListener('submit', saveStaff); $('#add-price-tier').addEventListener('click', () => addPriceTierRow()); $('#new-product').addEventListener('click', () => openProductForm()); $('#product-form').addEventListener('submit', saveProduct); $('#new-movement').addEventListener('click', () => { $('#movement-form').reset(); $('#movement-error').textContent = ''; openModal('movement-modal'); }); $('#movement-form').addEventListener('submit', saveMovement);   $('#new-expense').addEventListener('click', () => { const f=$('#expense-form'); f.reset(); f.elements.id.value=''; $('#expense-modal-title').textContent='Registrar despesa'; f.elements.expenseDate.value=new Date().toISOString().slice(0,10); openModal('expense-modal'); }); $('#expense-form').addEventListener('submit', saveExpense); $('#new-payable').addEventListener('click', () => { const f=$('#payable-form'); f.reset(); f.elements.id.value=''; $('#payable-modal-title').textContent='Nova conta a pagar'; f.elements.dueDate.value=new Date().toISOString().slice(0,10); openModal('payable-modal'); }); $('#payable-form').addEventListener('submit', savePayable); $('#new-campaign').addEventListener('click', () => openCampaignForm()); $('#add-campaign-product').addEventListener('click', () => addCampaignProductRow()); $('#campaign-form').addEventListener('submit', saveCampaign); $('#campaign-orders-select').addEventListener('change', loadCampaignOrders); $('#new-supplier').addEventListener('click',()=>{ $('#supplier-form').reset(); $('#supplier-error').textContent=''; openModal('supplier-modal'); }); $('#supplier-form').addEventListener('submit',saveSupplier); $('#new-purchase').addEventListener('click',async()=>{ $('#purchase-form').reset(); $('#purchase-form').elements.purchaseDate.value=new Date().toISOString().slice(0,10); $('#purchase-error').textContent=''; await loadPurchases(); openModal('purchase-modal'); }); $('#purchase-form').addEventListener('submit',savePurchase); $('#refresh-whatsapp').addEventListener('click', loadWhatsapp);
  $('#product-image').addEventListener('change', event => { const file = event.target.files[0]; if (file) setProductPreview(URL.createObjectURL(file)); });
  $('#reconnect-whatsapp').addEventListener('click', async () => { const button = $('#reconnect-whatsapp'); button.disabled = true; try { await api('/api/admin/whatsapp/reconnect', { method: 'POST' }); toast('Reconexão iniciada. Aguarde o QR Code.'); setSection('whatsapp'); setTimeout(loadWhatsapp, 1200); } catch (error) { toast(error.message); } finally { button.disabled = false; } });
  $('#logout-whatsapp').addEventListener('click', async () => { if (!confirm('Encerrar a sessão atual do WhatsApp Web?')) return; try { await api('/api/admin/whatsapp/logout', { method: 'POST' }); toast('Sessão encerrada.'); loadWhatsapp(); } catch (error) { toast(error.message); } });
}
function resetStaffForm(staff=null){const f=$('#staff-form');f.reset();f.elements.id.value=staff?.id||'';$('#staff-modal-title').textContent=staff?'Editar membro da equipe':'Novo membro da equipe';if(staff){f.elements.name.value=staff.name||'';f.elements.phone.value=staff.phone||'';['canSell','canPick','canDeliver','canViewFinancial','canManageProducts','canAttend','canApproveCustomers','isAdmin'].forEach(k=>f.elements[k].checked=Boolean(staff[k]));f.dataset.active=staff.active?'1':'0';}else f.dataset.active='1';$('#staff-error').textContent='';openModal('staff-modal');}
async function loadStaff(){try{const {staff}=await api('/api/admin/staff');state.staff=staff;$('#staff-table').innerHTML=staff.length?`<table class="data-table"><thead><tr><th>Nome</th><th>WhatsApp</th><th>Permissões</th><th>Status</th><th></th></tr></thead><tbody>${staff.map(i=>{const p=[i.canSell&&'Vender',i.canPick&&'Separar',i.canDeliver&&'Entregar',i.canViewFinancial&&'Financeiro',i.canManageProducts&&'Produtos',i.canAttend&&'Atendimento'].filter(Boolean);return `<tr><td><strong>${escapeHtml(i.name)}</strong></td><td>${escapeHtml(i.phone)}</td><td>${p.join(' · ')||'Nenhuma'}</td><td>${i.active?'Ativo':'Inativo'}</td><td><button class="table-action" data-edit-staff="${i.id}" type="button">Editar</button><button class="table-action" data-toggle-staff="${i.id}" type="button">${i.active?'Desativar':'Ativar'}</button></td></tr>`}).join('')}</tbody></table>`:'<div class="empty-state"><strong>Nenhum membro cadastrado.</strong></div>';$('#staff-table').querySelectorAll('[data-edit-staff]').forEach(b=>b.onclick=()=>resetStaffForm(staff.find(x=>x.id===Number(b.dataset.editStaff))));$('#staff-table').querySelectorAll('[data-toggle-staff]').forEach(b=>{b.onclick=async()=>{const x=staff.find(x=>x.id===Number(b.dataset.toggleStaff));try{await api(`/api/admin/staff/${x.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({active:!x.active})});toast('Status atualizado.');loadStaff();}catch(e){toast(e.message)}}});}catch(e){toast(e.message)}}
async function saveStaff(e){e.preventDefault();const f=e.target,id=Number(f.elements.id.value)||0;const payload={name:f.elements.name.value,phone:f.elements.phone.value,active:f.dataset.active!=='0',canSell:f.elements.canSell.checked,canPick:f.elements.canPick.checked,canDeliver:f.elements.canDeliver.checked,canViewFinancial:f.elements.canViewFinancial.checked,canManageProducts:f.elements.canManageProducts.checked,canAttend:f.elements.canAttend.checked,canApproveCustomers:f.elements.canApproveCustomers.checked,isAdmin:f.elements.isAdmin.checked};try{await api(id?`/api/admin/staff/${id}`:'/api/admin/staff',{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});closeModal('staff-modal');toast(id?'Membro atualizado.':'Membro cadastrado.');loadStaff();}catch(e){$('#staff-error').textContent=e.message;}}
async function loadExpenses(){try{const {expenses}=await api('/api/admin/expenses');$('#expenses-table').innerHTML=expenses.length?`<table class="data-table"><thead><tr><th>Data</th><th>Descrição</th><th>Categoria</th><th>Valor</th><th></th></tr></thead><tbody>${expenses.map(i=>`<tr><td>${dateBR(i.expense_date)}</td><td><strong>${escapeHtml(i.description)}</strong></td><td>${escapeHtml(i.category)}</td><td>${money(i.amount)}</td><td><button class="table-action" data-edit-expense="${i.id}" type="button">Editar</button><button class="table-action danger" data-delete-expense="${i.id}" type="button">Remover</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty-state"><strong>Nenhuma despesa cadastrada.</strong></div>';$('#expenses-table').querySelectorAll('[data-edit-expense]').forEach(b=>b.onclick=()=>{const i=expenses.find(x=>x.id===Number(b.dataset.editExpense));const f=$('#expense-form');f.reset();f.elements.id.value=i.id;f.elements.description.value=i.description;f.elements.amount.value=Number(i.amount).toFixed(2).replace('.',',');f.elements.category.value=i.category;f.elements.expenseDate.value=i.expense_date;$('#expense-modal-title').textContent='Editar despesa';openModal('expense-modal')});$('#expenses-table').querySelectorAll('[data-delete-expense]').forEach(b=>b.onclick=async()=>{if(!confirm('Remover esta despesa?'))return;try{await api(`/api/admin/expenses/${b.dataset.deleteExpense}`,{method:'DELETE'});toast('Despesa removida.');loadExpenses();loadDashboard()}catch(e){toast(e.message)}});}catch(e){toast(e.message)}}
async function saveExpense(e){e.preventDefault();const f=e.target,id=Number(f.elements.id.value)||0;try{await api(id?`/api/admin/expenses/${id}`:'/api/admin/expenses',{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({description:f.elements.description.value,amount:f.elements.amount.value,category:f.elements.category.value,expenseDate:f.elements.expenseDate.value})});closeModal('expense-modal');f.reset();toast(id?'Despesa atualizada.':'Despesa registrada.');loadExpenses();loadDashboard();}catch(e){$('#expense-error').textContent=e.message}}
async function loadPayables(){try{const data=await api('/api/admin/payables'),s=data.summary;$('#payables-summary').innerHTML=`<div class="metric-card ${s.overdueCount?'accent':''}"><span>Vencidas</span><strong>${s.overdueCount}</strong><small>${money(s.overdueTotal)}</small></div><div class="metric-card"><span>Próximos 7 dias</span><strong>${s.next7Count}</strong><small>${money(s.next7Total)}</small></div><div class="metric-card"><span>Total em aberto</span><strong>${s.pendingCount}</strong><small>${money(s.pendingTotal)}</small></div>`;$('#payables-table').innerHTML=data.payables.length?`<table class="data-table"><thead><tr><th>Vencimento</th><th>Credor</th><th>Descrição</th><th>Valor</th><th>Status</th><th></th></tr></thead><tbody>${data.payables.map(i=>`<tr><td>${dateBR(i.due_date)}</td><td>${escapeHtml(i.creditor)}</td><td>${escapeHtml(i.description)}<small class="table-sub">${escapeHtml(i.category)}</small></td><td><strong>${money(i.amount)}</strong></td><td>${statusPill(i.status)}</td><td><button class="table-action" data-edit-payable="${i.id}" type="button">Editar</button>${i.status==='pending'?`<button class="table-action" data-payable-paid="${i.id}" type="button">Marcar pago</button><button class="table-action danger" data-payable-cancel="${i.id}" type="button">Cancelar</button>`:''}</td></tr>`).join('')}</tbody></table>`:'<div class="empty-state"><strong>Nenhuma conta cadastrada.</strong></div>';$('#payables-table').querySelectorAll('[data-edit-payable]').forEach(b=>b.onclick=()=>{const i=data.payables.find(x=>x.id===Number(b.dataset.editPayable));const f=$('#payable-form');f.reset();f.elements.id.value=i.id;f.elements.creditor.value=i.creditor;f.elements.description.value=i.description;f.elements.amount.value=Number(i.amount).toFixed(2).replace('.',',');f.elements.dueDate.value=i.due_date;f.elements.category.value=i.category;f.elements.recurrence.value=i.recurrence;f.elements.notes.value=i.notes||'';$('#payable-modal-title').textContent='Editar conta a pagar';openModal('payable-modal')});$('#payables-table').querySelectorAll('[data-payable-paid]').forEach(b=>b.onclick=async()=>{try{await api(`/api/admin/payables/${b.dataset.payablePaid}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:'paid',paidDate:new Date().toISOString().slice(0,10)})});toast('Conta paga.');loadPayables();loadDashboard()}catch(e){toast(e.message)}});$('#payables-table').querySelectorAll('[data-payable-cancel]').forEach(b=>b.onclick=async()=>{if(!confirm('Cancelar esta conta?'))return;try{await api(`/api/admin/payables/${b.dataset.payableCancel}`,{method:'DELETE'});toast('Conta cancelada.');loadPayables()}catch(e){toast(e.message)}});}catch(e){toast(e.message)}}
async function savePayable(e){e.preventDefault();const f=e.target,id=Number(f.elements.id.value)||0;try{await api(id?`/api/admin/payables/${id}`:'/api/admin/payables',{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({creditor:f.elements.creditor.value,description:f.elements.description.value,amount:f.elements.amount.value,dueDate:f.elements.dueDate.value,category:f.elements.category.value,recurrence:f.elements.recurrence.value,notes:f.elements.notes.value})});closeModal('payable-modal');f.reset();toast(id?'Conta atualizada.':'Conta cadastrada.');loadPayables();}catch(e){$('#payable-error').textContent=e.message}}
function addCampaignProductRow(values={}){const wrap=$('#campaign-product-editor'),row=document.createElement('div');row.className='campaign-product-row';row.dataset.id=values.id||'';row.innerHTML=`<label>Nome<input name="cpName" required value="${escapeHtml(values.name||'')}"></label><label>Descrição<input name="cpDescription" value="${escapeHtml(values.description||'')}"></label><label>Unidade<select name="cpUnit"><option value="un" ${values.unit==='un'?'selected':''}>un.</option><option value="g" ${values.unit==='g'?'selected':''}>g</option><option value="kg" ${values.unit==='kg'?'selected':''}>kg</option><option value="ml" ${values.unit==='ml'?'selected':''}>ml</option><option value="L" ${values.unit==='L'?'selected':''}>L</option></select></label><label>Preço final<input name="cpPrice" required inputmode="decimal" value="${values.price??''}"></label><label>Custo admin<input name="cpCost" inputmode="decimal" value="${values.cost??''}"></label><label>Mínimo<input name="cpMin" type="number" min="0" step="0.01" value="${values.minQty??0}"></label><label>Disponível<input name="cpAvailable" type="number" min="0" step="0.01" value="${values.availableQty??''}" placeholder="ilimitado"></label><label>Status<select name="cpStatus"><option value="waiting" ${values.availabilityStatus==='waiting'?'selected':''}>Aguardando</option><option value="available" ${values.availabilityStatus==='available'?'selected':''}>Disponível</option><option value="unavailable" ${values.availabilityStatus==='unavailable'?'selected':''}>Indisponível</option></select></label><button class="table-action remove-campaign-product" type="button">Remover</button>`;row.querySelector('.remove-campaign-product').onclick=()=>row.remove();wrap.appendChild(row)}
function campaignProductsFromForm(){return $$('#campaign-product-editor .campaign-product-row').map(row=>({id:Number(row.dataset.id)||undefined,name:row.querySelector('[name=cpName]').value.trim(),description:row.querySelector('[name=cpDescription]').value.trim(),unit:row.querySelector('[name=cpUnit]').value,price:row.querySelector('[name=cpPrice]').value,cost:row.querySelector('[name=cpCost]').value,minQty:row.querySelector('[name=cpMin]').value,availableQty:row.querySelector('[name=cpAvailable]').value,availabilityStatus:row.querySelector('[name=cpStatus]').value})).filter(x=>x.name)}
function openCampaignForm(c){const f=$('#campaign-form');f.reset();f.elements.id.value=c?.id||'';$('#campaign-modal-title').textContent=c?'Editar campanha':'Nova campanha';$('#campaign-submit').textContent=c?'Salvar alterações':'Criar campanha';f.elements.name.value=c?.name||'';f.elements.description.value=c?.description||'';f.elements.startDate.value=c?.start_date||new Date().toISOString().slice(0,10);f.elements.endDate.value=c?.end_date||new Date().toISOString().slice(0,10);f.elements.paymentDueDate.value=c?.payment_due_date||'';f.elements.deliveryDate.value=c?.delivery_date||'';$('#campaign-product-editor').innerHTML='';(c?.campaignProducts||[]).forEach(addCampaignProductRow);if(!c)addCampaignProductRow();$('#campaign-error').textContent='';openModal('campaign-modal')}
async function loadCampaigns(){try{const {campaigns}=await api('/api/admin/campaigns');state.campaigns=campaigns;$('#campaigns-table').innerHTML=campaigns.length?`<table class="data-table"><thead><tr><th>Campanha</th><th>Período</th><th>Produtos</th><th>Pedidos</th><th>Recebido</th><th>Status</th><th>Ações</th></tr></thead><tbody>${campaigns.map(c=>`<tr><td><strong>${escapeHtml(c.name)}</strong><small class="table-sub">${escapeHtml(c.description||'')}</small></td><td>${dateBR(c.start_date)} até ${dateBR(c.end_date)}</td><td>${c.campaignProducts?.length||0}</td><td>${c.orderCount||0}</td><td>${c.orderPaid||'R$ 0,00'}</td><td>${c.active?'Ativa':'Inativa'}</td><td><button class="table-action" data-edit-campaign="${c.id}" type="button">Editar</button><button class="table-action" data-campaign-link="${c.id}" type="button">Gerar link</button><button class="table-action" data-toggle-campaign="${c.id}" type="button">${c.active?'Ocultar':'Publicar'}</button><button class="table-action danger" data-delete-campaign="${c.id}" type="button">Arquivar</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty-state"><strong>Nenhuma campanha cadastrada.</strong></div>';$('#campaign-orders-select').innerHTML='<option value="">Selecione a campanha</option>'+campaigns.map(c=>`<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('');$('#campaigns-table').querySelectorAll('[data-edit-campaign]').forEach(b=>b.onclick=()=>openCampaignForm(campaigns.find(c=>c.id===Number(b.dataset.editCampaign))));$('#campaigns-table').querySelectorAll('[data-toggle-campaign]').forEach(b=>b.onclick=async()=>{const c=campaigns.find(x=>x.id===Number(b.dataset.toggleCampaign));try{await api(`/api/admin/campaigns/${c.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({active:!c.active})});toast('Status da campanha atualizado.');loadCampaigns()}catch(e){toast(e.message)}});$('#campaigns-table').querySelectorAll('[data-delete-campaign]').forEach(b=>b.onclick=async()=>{if(!confirm('Arquivar esta campanha? O histórico será preservado.'))return;try{await api(`/api/admin/campaigns/${b.dataset.deleteCampaign}`,{method:'DELETE'});toast('Campanha arquivada.');loadCampaigns()}catch(e){toast(e.message)}});$('#campaigns-table').querySelectorAll('[data-campaign-link]').forEach(b=>b.onclick=async()=>{try{const d=await api('/api/admin/campaign-links',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({campaignId:Number(b.dataset.campaignLink)})});try{await navigator.clipboard.writeText(d.url);toast('Link seguro criado e copiado.')}catch{window.prompt('Copie o link da campanha:',d.url)}}catch(e){toast(e.message)}})}catch(e){toast(e.message)}}
async function saveCampaign(e){e.preventDefault();const f=e.target,id=Number(f.elements.id.value)||0;try{const products=campaignProductsFromForm();if(!products.length)throw Error('Cadastre pelo menos um produto da campanha.');await api(id?`/api/admin/campaigns/${id}`:'/api/admin/campaigns',{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:f.elements.name.value,description:f.elements.description.value,startDate:f.elements.startDate.value,endDate:f.elements.endDate.value,paymentDueDate:f.elements.paymentDueDate.value,deliveryDate:f.elements.deliveryDate.value,products})});closeModal('campaign-modal');toast(id?'Campanha atualizada.':'Campanha criada.');loadCampaigns();}catch(e){$('#campaign-error').textContent=e.message}}
async function loadCampaignOrders(){const id=Number($('#campaign-orders-select').value);if(!id){$('#campaign-orders-table').innerHTML='<div class="empty-state"><strong>Selecione uma campanha.</strong></div>';return}try{const {orders}=await api(`/api/admin/campaign-orders?campaignId=${id}`);$('#campaign-orders-table').innerHTML=orders.length?`<table class="data-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Total</th><th>Pagamento</th><th>Disponibilidade</th><th>Ações</th></tr></thead><tbody>${orders.map(o=>`<tr><td><strong>${escapeHtml(o.order_number)}</strong><small class="table-sub">${dateBR(o.created_at)}</small></td><td>${escapeHtml(o.customer_name)}<small class="table-sub">${escapeHtml(o.customer_phone)}</small></td><td><strong>${o.total}</strong><small class="table-sub">Pago: ${o.paid} · Falta: ${o.remaining}</small></td><td><button class="table-action" data-campaign-pay="${o.id}" type="button">Registrar pagamento</button><small class="table-sub">${o.paymentDate?`Em ${dateBR(o.paymentDate)}`:'Sem data'}</small></td><td>${o.items.map(i=>`<div style="padding:5px 0"><strong>${escapeHtml(i.name)}</strong> — ${i.quantity} ${escapeHtml(i.unit)}<br><select class="status-select" data-campaign-item="${i.campaignProductId}"><option value="waiting" ${i.availabilityStatus==='waiting'?'selected':''}>🟡 Aguardando</option><option value="available" ${i.availabilityStatus==='available'?'selected':''}>🟢 Disponível</option><option value="unavailable" ${i.availabilityStatus==='unavailable'?'selected':''}>🔴 Indisponível</option></select></div>`).join('')}</td><td><button class="table-action" data-campaign-status="${o.id}" type="button">Status</button><button class="table-action" data-campaign-production="${o.id}" type="button">${o.productionStarted?'Parar produção':'Iniciar produção'}</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty-state"><strong>Nenhum pedido.</strong></div>';
$('#campaign-orders-table').querySelectorAll('[data-campaign-pay]').forEach(b=>b.onclick=async()=>{const o=orders.find(x=>x.id===Number(b.dataset.campaignPay));const val=prompt(`Valor pago pelo cliente. Total ${o.total}.\nDigite o valor acumulado:`,Number(o.paidCents||0).toFixed(2).replace('.',','));if(val===null)return;try{await api(`/api/admin/campaign-orders/${o.id}/payment`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({paidAmount:val,paymentDate:new Date().toISOString().slice(0,10)})});toast('Pagamento atualizado.');loadCampaignOrders();}catch(e){toast(e.message)}});
$('#campaign-orders-table').querySelectorAll('[data-campaign-item]').forEach(b=>b.onchange=async()=>{try{await api(`/api/admin/campaign-products/${b.dataset.campaignItem}/availability`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({availabilityStatus:b.value})});toast('Disponibilidade atualizada.');loadCampaignOrders()}catch(e){toast(e.message)}});
$('#campaign-orders-table').querySelectorAll('[data-campaign-status]').forEach(b=>b.onclick=async()=>{const o=orders.find(x=>x.id===Number(b.dataset.campaignStatus));const status=prompt('Status: open, confirmed ou cancelled',o.status);if(!status)return;try{await api(`/api/admin/campaign-orders/${o.id}/status`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})});loadCampaignOrders()}catch(e){toast(e.message)}});
$('#campaign-orders-table').querySelectorAll('[data-campaign-production]').forEach(b=>b.onclick=async()=>{const o=orders.find(x=>x.id===Number(b.dataset.campaignProduction));try{await api(`/api/admin/campaign-orders/${o.id}/production`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({started:!o.productionStarted})});toast('Produção atualizada.');loadCampaignOrders()}catch(e){toast(e.message)}});
}catch(e){toast(e.message)}}
async function loadPurchases(){try{const [{suppliers},{products},{campaigns},{purchases}]=await Promise.all([api('/api/admin/suppliers'),api('/api/admin/products'),api('/api/admin/campaigns'),api('/api/admin/purchases')]);state.suppliers=suppliers;state.products=products;state.campaigns=campaigns;$('#suppliers-table').innerHTML=suppliers.length?`<table class="data-table"><thead><tr><th>Fornecedor</th><th>WhatsApp</th><th>Observações</th><th></th></tr></thead><tbody>${suppliers.map(s=>`<tr><td><strong>${escapeHtml(s.name)}</strong></td><td>${escapeHtml(s.phone||'—')}</td><td>${escapeHtml(s.notes||'—')}</td><td><button class="table-action" data-edit-supplier="${s.id}" type="button">Editar</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty-state"><strong>Nenhum fornecedor.</strong></div>';$('#purchases-table').innerHTML=purchases.length?`<table class="data-table"><thead><tr><th>Data</th><th>Produto</th><th>Fornecedor</th><th>Quantidade</th><th>Preço</th><th>Total</th><th>Campanha</th><th>Status</th><th></th></tr></thead><tbody>${purchases.map(p=>`<tr><td>${dateBR(p.purchase_date)}</td><td>${escapeHtml(p.product_name)}</td><td>${escapeHtml(p.supplier_name)}</td><td>${p.quantity}</td><td>${p.unitCost}</td><td>${p.totalCost}</td><td>${escapeHtml(p.campaign_name||'—')}</td><td>${escapeHtml(p.status)}</td><td><button class="table-action" data-edit-purchase="${p.id}" type="button">Editar</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty-state"><strong>Nenhuma compra registrada.</strong></div>';
$('#purchase-form [name=supplierId]').innerHTML='<option value="">Selecione</option>'+suppliers.filter(x=>x.active).map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('');$('#purchase-form [name=productId]').innerHTML='<option value="">Selecione</option>'+products.filter(x=>x.active).map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('');$('#purchase-form [name=campaignId]').innerHTML='<option value="">Sem campanha</option>'+campaigns.map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('');
$('#suppliers-table').querySelectorAll('[data-edit-supplier]').forEach(b=>b.onclick=()=>{const s=suppliers.find(x=>x.id===Number(b.dataset.editSupplier)),f=$('#supplier-form');f.reset();f.elements.id.value=s.id;f.elements.name.value=s.name;f.elements.phone.value=s.phone||'';f.elements.notes.value=s.notes||'';$('#supplier-modal-title').textContent='Editar fornecedor';openModal('supplier-modal')});
$('#purchases-table').querySelectorAll('[data-edit-purchase]').forEach(b=>b.onclick=()=>{const x=purchases.find(y=>y.id===Number(b.dataset.editPurchase)),f=$('#purchase-form');f.reset();f.elements.id.value=x.id;f.elements.supplierId.value=x.supplier_id;f.elements.productId.value=x.product_id;f.elements.campaignId.value=x.campaign_id||'';f.elements.quantity.value=x.quantity;f.elements.unitCost.value=(Number(x.unit_cost_cents||0)/100).toFixed(2).replace('.',',');f.elements.purchaseDate.value=x.purchase_date;f.elements.status.value=x.status;f.elements.notes.value=x.notes||'';$('#purchase-modal-title').textContent='Editar compra';openModal('purchase-modal')});}catch(e){toast(e.message)}}
async function saveSupplier(e){e.preventDefault();const f=e.target,id=Number(f.elements.id.value)||0;try{await api(id?`/api/admin/suppliers/${id}`:'/api/admin/suppliers',{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:f.elements.name.value,phone:f.elements.phone.value,notes:f.elements.notes.value})});closeModal('supplier-modal');toast(id?'Fornecedor atualizado.':'Fornecedor cadastrado.');loadPurchases();}catch(e){$('#supplier-error').textContent=e.message}}
async function savePurchase(e){e.preventDefault();const f=e.target,id=Number(f.elements.id.value)||0;try{await api(id?`/api/admin/purchases/${id}`:'/api/admin/purchases',{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({supplierId:f.elements.supplierId.value,productId:f.elements.productId.value,campaignId:f.elements.campaignId.value,quantity:f.elements.quantity.value,unitCost:f.elements.unitCost.value,purchaseDate:f.elements.purchaseDate.value,status:f.elements.status.value,addToStock:f.elements.addToStock.checked,notes:f.elements.notes.value})});closeModal('purchase-modal');toast(id?'Compra atualizada.':'Compra registrada.');loadPurchases();}catch(e){$('#purchase-error').textContent=e.message}}

boot();

function startWhatsappPolling() { stopWhatsappPolling(); state.whatsappTimer = setInterval(() => { if (state.currentSection === 'whatsapp') loadWhatsapp(); }, 4000); }

function stopWhatsappPolling() { if (state.whatsappTimer) { clearInterval(state.whatsappTimer); state.whatsappTimer = null; } }

async function loadWhatsapp() { try { const status = await api('/api/admin/whatsapp/status'); $('#whatsapp-number').textContent = status.number ? `Número conectado: ${status.number}` : (status.configuredNumber ? `Número configurado: ${status.configuredNumber}` : 'Número não configurado'); const labels = { connected: 'Conectado', qr: 'Aguardando leitura do QR Code', disconnected: 'Desconectado', logged_out: 'Sessão encerrada', offline: 'Serviço offline', error: 'Erro na sessão', starting: 'Iniciando', reconnecting: 'Reconectando', authenticated: 'Autenticado' }; $('#whatsapp-note').textContent = status.lastError || labels[status.status] || status.note || 'Status atualizado.'; $('#whatsapp-status').textContent = labels[status.status] || (status.connected ? 'Conectado' : 'Desconectado'); $('#whatsapp-status').className = `status-pill ${status.connected ? 'paid' : status.status === 'qr' ? 'pending' : 'off'}`; $('#whatsapp-qr').innerHTML = status.qrDataUrl ? `<img src="${status.qrDataUrl}" alt="QR Code para conectar o WhatsApp Web" style="width:140px;height:140px;object-fit:contain">` : 'QR Code<br><small>não disponível agora</small>'; } catch (error) { toast(error.message); } }
